
(()=>{"use strict";
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const en=()=>document.documentElement.lang==="en"||document.documentElement.dir==="ltr";
const tr=(he,enText)=>en()?enText:he;
async function api(path,opts={}){const init={credentials:"same-origin",...opts,headers:{...(opts.headers||{})}};if(opts.body&&!(opts.body instanceof FormData)){init.headers["Content-Type"]="application/json";init.body=JSON.stringify(opts.body)}let r;try{r=await fetch(path,init)}catch(e){throw new Error(window.GmachDescribeNetworkError?window.GmachDescribeNetworkError(e):tr("לא ניתן להתחבר לשרת","Could not connect to the server"))}const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(window.GmachDescribeHttpError?window.GmachDescribeHttpError(r,d):(d.error||tr("הפעולה לא הושלמה","Action failed")));return d}
function toast(msg,bad=false){if(window.GmachToast)return window.GmachToast(msg,bad?"error":"success");}
function dialog(id,title){let d=$("#"+id);if(!d){d=document.createElement("dialog");d.id=id;d.className="modal modal-wide";document.body.append(d)}d.innerHTML='<button class="dialog-close" type="button" aria-label="'+tr("סגירה","Close")+'">×</button><h2>'+esc(title)+'</h2><div class="requirements-expansion-body"></div>';$(".dialog-close",d).onclick=()=>d.close();return d}
function fmt(v){if(!v)return"";try{return new Intl.DateTimeFormat(en()?"en-GB":"he-IL",{dateStyle:"medium",timeStyle:"short"}).format(new Date(v))}catch{return String(v)}}

async function openMultiRange(itemId){
 const d=dialog("multi-range-dialog",tr("תכנון כמה טווחי השאלה","Plan multiple loan periods")),body=$(".requirements-expansion-body",d);
 body.innerHTML='<p>'+tr("אפשר לבדוק ולשלוח עד שמונה טווחים באותה פעולה. כל טווח יוצר בקשת השאלה נפרדת המקושרת לקבוצה אחת.","Check and submit up to eight periods at once. Each period becomes a separate linked loan request.")+'</p><form id="multi-range-form" class="stack-form"><label>'+tr("כמות בכל טווח","Quantity per period")+'<input name="quantity" type="number" min="1" max="999" value="1" required></label><div id="multi-range-rows"></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button type="button" class="button button-secondary" id="multi-add-range">'+tr("הוספת טווח","Add period")+'</button><button type="button" class="button button-secondary" id="multi-check">'+tr("בדיקת זמינות","Check availability")+'</button><button type="submit" class="button button-primary">'+tr("שליחת כל הבקשות","Submit all requests")+'</button></div><div id="multi-range-result" aria-live="polite"></div></form>';
 const rows=$("#multi-range-rows",d),result=$("#multi-range-result",d);let count=0;
 const add=()=>{if(count>=8)return;count++;const row=document.createElement("div");row.className="two-columns";row.dataset.rangeRow="1";row.innerHTML='<label>'+tr("איסוף","Pickup")+'<input name="from" type="datetime-local" required></label><label>'+tr("החזרה","Return")+'<input name="until" type="datetime-local" required></label>';rows.append(row)};
 add();add();$("#multi-add-range",d).onclick=add;
 const payload=()=>({quantity:Number($("#multi-range-form",d).quantity.value||1),ranges:$$("[data-range-row]",d).map(r=>({from:$('input[name="from"]',r).value,until:$('input[name="until"]',r).value})).filter(x=>x.from&&x.until)});
 $("#multi-check",d).onclick=async()=>{try{const x=await api("/api/items/"+encodeURIComponent(itemId)+"/multi-range-check",{method:"POST",body:payload()});result.innerHTML=x.ranges.map((r,i)=>'<p><strong>'+(i+1)+'.</strong> '+esc(fmt(r.from))+' - '+esc(fmt(r.until))+' · '+(r.available?tr("זמין","Available"):tr("לא זמין","Unavailable"))+' ('+Number(r.availableQuantity||0)+')</p>').join("");}catch(e){result.innerHTML='<p role="alert">'+esc(e.message)+'</p>'}};
 $("#multi-range-form",d).onsubmit=async e=>{e.preventDefault();if(!confirm(tr("לשלוח את כל הטווחים כבקשות נפרדות?","Submit all periods as separate requests?")))return;try{const x=await api("/api/items/"+encodeURIComponent(itemId)+"/multi-range-request",{method:"POST",body:payload()});toast(tr("נשלחו "+x.count+" בקשות מקושרות","Submitted "+x.count+" linked requests"));d.close()}catch(err){toast(err.message,true)}};
 d.showModal();
}
function installItemMultiRange(){
 const host=$("#item-dialog-content"),itemId=host?.dataset.itemId;if(!host||!itemId||host.querySelector("[data-multi-range]"))return;
 const actions=$(".detail-actions",host);if(!actions)return;const b=document.createElement("button");b.type="button";b.className="button button-secondary";b.dataset.multiRange="1";b.textContent=tr("כמה טווחים","Multiple periods");b.onclick=()=>openMultiRange(itemId);actions.append(b);
}

async function openBranches(orgId){
 const d=dialog("public-branches-dialog",tr("סניפים ונקודות איסוף","Branches and pickup points")),body=$(".requirements-expansion-body",d);body.innerHTML="<p>"+tr("טוענים...","Loading...")+"</p>";d.showModal();
 try{const x=await api("/api/organizations/"+encodeURIComponent(orgId)+"/branches-public");const branches=x.branches||[];body.innerHTML=branches.length?'<div style="display:grid;gap:10px">'+branches.map(b=>{const hours=Object.entries(b.hours||{}).map(([day,value])=>esc(day)+": "+esc(value)).join(" · ");const status=b.status==="temporarily_closed"?(tr("סגור זמנית","Temporarily closed")+(b.reopens_at?" · "+tr("פתיחה","Reopens")+": "+esc(fmt(b.reopens_at)):"")):esc(b.status);return '<article class="dashboard-row"><div><strong>'+esc(b.name)+'</strong><p>'+esc(b.address)+' · '+esc(b.city)+(b.phone?' · <a href="tel:'+esc(b.phone)+'" dir="ltr">'+esc(b.phone)+'</a>':'')+'</p>'+(hours?'<p><strong>'+tr("שעות פעילות","Hours")+':</strong> '+hours+'</p>':'')+'<small>'+tr("סטטוס","Status")+': '+status+' · '+tr("יחידות זמינות","Available units")+': '+Number(b.availableUnits||0)+(b.rating?' · ⭐ '+esc(b.rating)+' ('+Number(b.reviewCount||0)+')':'')+'</small></div><div style="display:flex;gap:6px;flex-wrap:wrap"><button class="button button-secondary button-small" type="button" data-copy-branch="'+esc(b.address)+'">'+tr("העתקת כתובת","Copy address")+'</button>'+(b.latitude!=null&&b.longitude!=null?'<a class="button button-secondary button-small" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(b.latitude+","+b.longitude)+'">Google Maps</a><a class="button button-secondary button-small" target="_blank" rel="noopener" href="https://waze.com/ul?ll='+encodeURIComponent(b.latitude+","+b.longitude)+'&navigate=yes">Waze</a>':'')+'</div></article>'}).join("")+'</div>':'<p>'+tr("לא הוגדרו סניפים ציבוריים.","No public branches are configured.")+'</p>';$$("[data-copy-branch]",body).forEach(button=>button.onclick=async()=>{try{await navigator.clipboard.writeText(button.dataset.copyBranch);toast(tr("הכתובת הועתקה","Address copied"))}catch{toast(tr("לא הצלחנו להעתיק את הכתובת","Could not copy the address"),true)}})}catch(e){body.innerHTML='<p role="alert">'+esc(e.message)+'</p>'}
}
function installBranchDirectory(){
 const host=$("#organization-dialog-content"),orgId=host?.dataset.organizationId;if(!host||!orgId||host.querySelector("[data-public-branches]"))return;
 const article=$(".organization-detail",host);if(!article)return;const b=document.createElement("button");b.type="button";b.className="button button-secondary";b.dataset.publicBranches="1";b.textContent=tr("כל הסניפים ונקודות האיסוף","All branches and pickup points");b.onclick=()=>openBranches(orgId);article.insertBefore(b,article.querySelector("h3"));
}

async function openMyReports(){
 const d=dialog("my-reports-dialog",tr("הדיווחים שלי","My reports")),body=$(".requirements-expansion-body",d);body.innerHTML="<p>"+tr("טוענים...","Loading...")+"</p>";d.showModal();
 try{const x=await api("/api/me/reports");body.innerHTML=(x.reports||[]).length?'<div style="display:grid;gap:8px">'+x.reports.map(r=>'<article class="dashboard-row"><div><strong>'+esc(r.entity_title||r.type)+'</strong><p>'+esc(r.reason||"")+(r.details?' · '+esc(r.details):'')+'</p><small>'+esc(fmt(r.created_at))+'</small></div><span class="status-chip">'+esc(r.status||"pending")+'</span></article>').join("")+'</div>':'<p>'+tr("אין דיווחים קודמים.","No previous reports.")+'</p>'}catch(e){body.innerHTML='<p role="alert">'+esc(e.message)+'</p>'}
}
function installReportsButton(){
 const actions=$("#dashboard-view .dashboard-actions");if(!actions||actions.querySelector("[data-my-reports]"))return;
 const b=document.createElement("button");b.type="button";b.className="button button-secondary";b.dataset.myReports="1";b.textContent=tr("הדיווחים שלי","My reports");b.onclick=openMyReports;actions.prepend(b);
}

async function openAdminUsers(){
 const d=dialog("admin-users-full-dialog",tr("ניהול משתמשים מתקדם","Advanced user management")),body=$(".requirements-expansion-body",d);body.innerHTML="<p>"+tr("טוענים...","Loading...")+"</p>";d.showModal();
 try{const x=await api("/api/admin/users");const users=x.users||[];body.innerHTML='<div class="two-columns" style="align-items:start"><div><input id="admin-user-search" type="search" placeholder="'+tr("חיפוש משתמש","Search user")+'" style="width:100%;margin-bottom:8px"><div id="admin-user-list" style="display:grid;gap:6px;max-height:60vh;overflow:auto"></div></div><div id="admin-user-detail"><p>'+tr("בחרו משתמש לצפייה מלאה.","Select a user for full details.")+'</p></div></div>';
 const list=$("#admin-user-list",d),detail=$("#admin-user-detail",d),renderList=q=>{const needle=String(q||"").toLowerCase();list.innerHTML=users.filter(u=>!needle||String(u.email+" "+u.full_name).toLowerCase().includes(needle)).map(u=>'<button type="button" class="button button-secondary" data-admin-user="'+esc(u.id)+'" style="text-align:start">'+window.GmachOriginalName(u.full_name)+'<small style="display:block">'+esc(u.email)+' · '+esc(u.account_status)+'</small></button>').join("");$$("[data-admin-user]",list).forEach(b=>b.onclick=()=>loadUser(b.dataset.adminUser))};renderList("");$("#admin-user-search",d).oninput=e=>renderList(e.target.value);
 async function loadUser(id){detail.innerHTML="<p>"+tr("טוענים...","Loading...")+"</p>";try{const u=await api("/api/admin/users/"+encodeURIComponent(id)+"/full"),x=u.user;detail.innerHTML='<h3>'+window.GmachOriginalName(x.full_name)+'</h3><p>'+esc(x.email)+' · '+esc(x.role)+' · <strong>'+esc(x.account_status)+'</strong></p><div style="display:flex;gap:6px;flex-wrap:wrap"><button class="button button-danger" data-user-suspend>'+tr("השבתה מיידית","Suspend now")+'</button><button class="button button-secondary" data-user-schedule>'+tr("השבתה מתוזמנת","Schedule suspension")+'</button><button class="button button-secondary" data-user-restore>'+tr("שחזור חשבון","Restore account")+'</button><button class="button button-secondary" data-user-revoke>'+tr("ניתוק כל המכשירים","Revoke all sessions")+'</button></div><h4>'+tr("השאלות","Loans")+' ('+(u.loans||[]).length+')</h4><div style="max-height:180px;overflow:auto">'+(u.loans||[]).slice(0,30).map(l=>'<p><strong>'+esc(l.title)+'</strong> · '+esc(l.status)+' · '+esc(l.workflow_status||"")+' <button class="button button-secondary button-small" data-loan-hold="'+esc(l.id)+'">'+tr("השהיה","Suspend")+'</button><button class="button button-secondary button-small" data-loan-resume="'+esc(l.id)+'">'+tr("המשך","Resume")+'</button></p>').join("")+'</div><h4>'+tr("מכשירים","Sessions")+' ('+(u.sessions||[]).length+')</h4><h4>'+tr("אירועי אבטחה","Security events")+' ('+(u.securityEvents||[]).length+')</h4><h4>'+tr("ביקורות","Reviews")+' ('+(u.reviews||[]).length+')</h4><h4>'+tr("דיווחים","Reports")+' ('+(u.reports||[]).length+')</h4><h4>'+tr("פעילות Audit","Audit activity")+' ('+(u.audit||[]).length+')</h4><a class="button button-secondary" href="/api/admin/audit/export.csv?actor_id='+encodeURIComponent(id)+'" download>'+tr("ייצוא פעילות CSV","Export activity CSV")+'</a>';
 const control=async body=>{try{await api("/api/admin/users/"+encodeURIComponent(id)+"/control",{method:"PATCH",body});toast(tr("הפעולה נשמרה","Action saved"));await loadUser(id)}catch(e){toast(e.message,true)}};
 $("[data-user-suspend]",detail).onclick=()=>{const reason=prompt(tr("סיבה להשבתה","Suspension reason"))||"";control({action:"suspend_now",reason})};
 $("[data-user-schedule]",detail).onclick=()=>{const startsAt=prompt(tr("מועד התחלה, לדוגמה 2026-10-01T10:00","Start time, for example 2026-10-01T10:00"));if(!startsAt)return;const endsAt=prompt(tr("מועד סיום, רשות","End time, optional"));control({action:"schedule_suspend",startsAt,endsAt:endsAt||null})};
 $("[data-user-restore]",detail).onclick=()=>control({action:"restore"});
 $("[data-user-revoke]",detail).onclick=()=>control({action:"revoke_sessions"});
 $$("[data-loan-hold]",detail).forEach(b=>b.onclick=async()=>{const reason=prompt(tr("סיבת השהיית ההשאלה","Loan suspension reason"))||tr("בדיקת מנהל","Admin review");try{await api("/api/admin/loan-requests/"+encodeURIComponent(b.dataset.loanHold)+"/control",{method:"PATCH",body:{action:"suspend",reason}});toast(tr("ההשאלה הושהתה","Loan suspended"));await loadUser(id)}catch(e){toast(e.message,true)}});
 $$("[data-loan-resume]",detail).forEach(b=>b.onclick=async()=>{try{await api("/api/admin/loan-requests/"+encodeURIComponent(b.dataset.loanResume)+"/control",{method:"PATCH",body:{action:"resume"}});toast(tr("ההשאלה חזרה לפעילות","Loan resumed"));await loadUser(id)}catch(e){toast(e.message,true)}});
 }catch(e){detail.innerHTML='<p role="alert">'+esc(e.message)+'</p>'}}
 }catch(e){body.innerHTML='<p role="alert">'+esc(e.message)+'</p>'}
}
function installAdminButton(){
 const tab=$("#admin-tab");if(!tab||tab.hidden)return;const actions=$("#dashboard-view .dashboard-actions");if(!actions||actions.querySelector("[data-admin-users-full]"))return;
 const b=document.createElement("button");b.type="button";b.className="button button-secondary";b.dataset.adminUsersFull="1";b.textContent=tr("ניהול משתמשים מתקדם","Advanced users");b.onclick=openAdminUsers;actions.prepend(b);
}

function init(){const obs=new MutationObserver(()=>{installItemMultiRange();installBranchDirectory();installReportsButton();installAdminButton()});obs.observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:["hidden","lang","dir"]});installReportsButton();installAdminButton();installItemMultiRange();installBranchDirectory()}
if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init,{once:true});else init();
})();
